/* CAW Social web viewer — v42 localization overrides.
   Hand-written translations for the web-only strings the
   Android app i18n table cannot supply: KEY_L10N covers the
   dict keys buildDict would otherwise leave in English,
   CHUNK_L10N covers the shell static chunks lookupChunk
   cannot resolve (keyed by the trimmed English chunk), and
   THEME_LABELS the shells' light/dark toggle labels.
   build-i18n.mjs validates that every KEY_L10N string
   carries exactly the placeholders of the English string;
   a mismatch fails the build. Proper nouns and token names
   (CAW, QL1, QOM, qCAW, PHOENIX, HAWK, Recaw, SuperLike,
   HuntersDEX, BurnHawk) stay as-is in every language.
   v43: the three tip keys left this table — the web tip
   strings match the app's HAWK strings again, so they map
   to the app table like the rest. */
