 "noGasQom": {
  "zh": "此钱包没有 QOM。少量 QOM 是支付小额费用所必需的，因此在有 QOM 之前发送会暂停。",
  "ko": "이 지갑에는 QOM이 없습니다. 작은 수수료를 위해 약간의 QOM이 필요하므로, 들어올 때까지 전송이 일시 중지됩니다.",
  "es": "Esta cartera no tiene QOM. Se necesita un poco de QOM para las pequeñas comisiones, así que el envío queda en pausa hasta que haya algo.",
  "tr": "Bu cüzdanda QOM yok. Küçük ücretler için biraz QOM gerekir, bu yüzden bir miktar gelene kadar gönderim duraklatılır.",
  "fa": "این کیف پول QOM ندارد. برای کارمزدهای کوچک کمی QOM لازم است، بنابراین تا وقتی مقداری نیاید ارسال متوقف می‌ماند.",
  "id": "Dompet ini tidak memiliki QOM. Sedikit QOM diperlukan untuk biaya kecil, jadi pengiriman dijeda sampai ada isinya.",
  "vi": "Ví này không có QOM. Cần một ít QOM cho các khoản phí nhỏ, nên việc gửi sẽ tạm dừng cho đến khi có một ít.",
  "th": "กระเป๋านี้ไม่มี QOM จำเป็นต้องมี QOM เล็กน้อยสำหรับค่าธรรมเนียมเล็ก ๆ ดังนั้นการส่งจะหยุดชั่วคราวจนกว่าจะมีเข้ามา",
  "it": "Questo wallet non contiene QOM. Un po’ di QOM serve per le piccole commissioni, quindi l’invio resta in pausa finché non ce n’è.",
  "pt": "Esta carteira não tem QOM. Um pouco de QOM é necessário para as pequenas taxas, então o envio fica pausado até que haja algum.",
  "nl": "Deze wallet bevat geen QOM. Er is een beetje QOM nodig voor de kleine vergoedingen, dus verzenden blijft gepauzeerd tot er iets in zit.",
  "pl": "Ten portfel nie ma QOM. Trochę QOM jest potrzebne na małe opłaty, więc wysyłanie pozostaje wstrzymane, dopóki coś się nie pojawi.",
  "uk": "У цьому гаманці немає QOM. Трохи QOM потрібно для невеликих комісій, тому надсилання призупинено, доки щось не з’явиться.",
  "de": "Diese Wallet enthält kein QOM. Etwas QOM wird für die kleinen Gebühren gebraucht, daher bleibt das Senden pausiert, bis etwas da ist.",
  "ru": "В этом кошельке нет QOM. Немного QOM нужно для небольших комиссий, поэтому отправка приостановлена, пока что-то не появится.",
  "ar": "هذه المحفظة لا تحتوي على QOM. يلزم القليل من QOM للرسوم الصغيرة، لذا يبقى الإرسال متوقفاً حتى يصل بعضها.",
  "hi": "इस वॉलेट में QOM नहीं है। छोटे शुल्कों के लिए थोड़ा QOM चाहिए, इसलिए कुछ आने तक भेजना रुका रहता है।",
  "fr": "Ce portefeuille ne contient aucun QOM. Un peu de QOM est nécessaire pour les petits frais, donc l’envoi reste en pause jusqu’à ce qu’il y en ait."
 },
