 "pwAddNote": {
  "zh": "此浏览器可以保存多个钱包。每个钱包保留自己的密码，添加一个不会改变其他钱包。",
  "ko": "이 브라우저는 지갑을 여러 개 보관할 수 있습니다. 각 지갑은 자체 비밀번호를 유지하며, 하나를 추가해도 다른 지갑은 변하지 않습니다.",
  "es": "Este navegador puede guardar más de una cartera. Cada cartera mantiene su propia contraseña, y añadir una no cambia las demás.",
  "tr": "Bu tarayıcı birden fazla cüzdan tutabilir. Her cüzdan kendi parolasını korur ve bir tane eklemek diğerlerini değiştirmez.",
  "fa": "این مرورگر می‌تواند بیش از یک کیف پول نگه دارد. هر کیف پول گذرواژه خودش را نگه می‌دارد و افزودن یکی، بقیه را تغییر نمی‌دهد.",
  "id": "Browser ini dapat menyimpan lebih dari satu dompet. Setiap dompet mempertahankan kata sandinya sendiri, dan menambahkan satu dompet tidak mengubah dompet lainnya.",
  "vi": "Trình duyệt này có thể chứa nhiều hơn một ví. Mỗi ví giữ mật khẩu riêng của nó, và việc thêm một ví không thay đổi các ví khác.",
  "th": "เบราว์เซอร์นี้เก็บกระเป๋าได้มากกว่าหนึ่งใบ แต่ละกระเป๋าเก็บรหัสผ่านของตัวเอง และการเพิ่มอีกใบจะไม่เปลี่ยนใบอื่น",
  "it": "Questo browser può contenere più di un wallet. Ogni wallet mantiene la propria password, e aggiungerne uno non cambia gli altri.",
  "pt": "Este navegador pode guardar mais de uma carteira. Cada carteira mantém sua própria senha, e adicionar uma não muda as outras.",
  "nl": "Deze browser kan meer dan één wallet bewaren. Elke wallet houdt zijn eigen wachtwoord, en er een toevoegen verandert de andere niet.",
  "pl": "Ta przeglądarka może trzymać więcej niż jeden portfel. Każdy portfel zachowuje własne hasło, a dodanie kolejnego nie zmienia pozostałych.",
  "uk": "Цей браузер може зберігати більше одного гаманця. Кожен гаманець зберігає власний пароль, і додавання ще одного не змінює інші.",
  "de": "Dieser Browser kann mehr als eine Wallet halten. Jede Wallet behält ihr eigenes Passwort, und eine weitere hinzuzufügen ändert die anderen nicht.",
  "ru": "Этот браузер может хранить больше одного кошелька. Каждый кошелёк сохраняет собственный пароль, и добавление ещё одного не меняет остальные.",
  "ar": "يمكن لهذا المتصفح أن يحتفظ بأكثر من محفظة واحدة. تحتفظ كل محفظة بكلمة مرورها الخاصة، وإضافة واحدة لا تغير الأخريات.",
  "hi": "यह ब्राउज़र एक से अधिक वॉलेट रख सकता है। प्रत्येक वॉलेट अपना पासवर्ड रखता है, और एक जोड़ने से दूसरे नहीं बदलते।",
  "fr": "Ce navigateur peut contenir plus d’un portefeuille. Chaque portefeuille garde son propre mot de passe, et en ajouter un ne change pas les autres."
 },
