 "pwRevealWarn": {
  "zh": "任何看到它的人都可以拿走这个钱包里的一切。切勿分享，切勿在其他网站输入，只在没人能看到你屏幕时查看。",
  "ko": "이것을 본 사람은 이 지갑 안의 모든 것을 가져갈 수 있습니다. 절대 공유하지 말고, 다른 사이트에 입력하지 말고, 아무도 화면을 볼 수 없을 때만 확인하세요.",
  "es": "Quien vea esto puede tomar todo lo que hay en esta cartera. Nunca lo compartas, nunca lo escribas en otro sitio, y míralo solo cuando nadie pueda ver tu pantalla.",
  "tr": "Bunu gören herkes bu cüzdandaki her şeyi alabilir. Asla paylaşmayın, asla başka bir siteye yazmayın ve yalnızca kimse ekranınızı göremediğinde bakın.",
  "fa": "هر کس این را ببیند می‌تواند همه چیز این کیف پول را بردارد. هرگز آن را به اشتراک نگذارید، هرگز آن را در سایت دیگری وارد نکنید و فقط وقتی نگاه کنید که هیچ‌کس صفحه شما را نمی‌بیند.",
  "id": "Siapa pun yang melihat ini dapat mengambil semua yang ada di dompet ini. Jangan pernah membagikannya, jangan pernah mengetiknya di situs lain, dan hanya lihat ketika tidak ada yang bisa melihat layar Anda.",
  "vi": "Bất kỳ ai thấy điều này đều có thể lấy mọi thứ trong ví này. Đừng bao giờ chia sẻ nó, đừng bao giờ nhập nó vào một trang khác, và chỉ xem khi không ai có thể thấy màn hình của bạn.",
  "th": "ใครก็ตามที่เห็นสิ่งนี้สามารถเอาทุกอย่างในกระเป๋านี้ไปได้ อย่าแชร์เด็ดขาด อย่าพิมพ์ลงในเว็บไซต์อื่น และดูเฉพาะเมื่อไม่มีใครเห็นหน้าจอของคุณ",
  "it": "Chiunque veda questo può prendere tutto ciò che c’è in questo wallet. Non condividerlo mai, non digitarlo mai in un altro sito, e guardalo solo quando nessuno può vedere il tuo schermo.",
  "pt": "Quem vir isto pode pegar tudo o que há nesta carteira. Nunca compartilhe, nunca digite em outro site, e olhe apenas quando ninguém puder ver sua tela.",
  "nl": "Iedereen die dit ziet, kan alles in deze wallet nemen. Deel het nooit, typ het nooit in op een andere site, en bekijk het alleen als niemand je scherm kan zien.",
  "pl": "Każdy, kto to zobaczy, może zabrać wszystko z tego portfela. Nigdy tego nie udostępniaj, nigdy nie wpisuj na innej stronie i patrz tylko wtedy, gdy nikt nie widzi twojego ekranu.",
  "uk": "Кожен, хто це побачить, може забрати все з цього гаманця. Ніколи не діліться цим, ніколи не вводьте на іншому сайті й дивіться лише тоді, коли ніхто не бачить ваш екран.",
  "de": "Wer dies sieht, kann alles in dieser Wallet nehmen. Teile es nie, tippe es nie auf einer anderen Seite ein und sieh es dir nur an, wenn niemand deinen Bildschirm sehen kann.",
  "ru": "Каждый, кто это увидит, может забрать всё из этого кошелька. Никогда не делитесь этим, никогда не вводите на другом сайте и смотрите только тогда, когда никто не видит ваш экран.",
  "ar": "كل من يرى هذا يمكنه أخذ كل شيء في هذه المحفظة. لا تشاركه أبداً، لا تكتبه أبداً في موقع آخر، وانظر إليه فقط عندما لا يستطيع أحد رؤية شاشتك.",
  "hi": "जो कोई भी यह देखता है, वह इस वॉलेट की हर चीज़ ले सकता है। इसे कभी साझा न करें, कभी किसी अन्य साइट पर न लिखें, और केवल तभी देखें जब कोई आपकी स्क्रीन न देख सके।",
  "fr": "Quiconque voit ceci peut prendre tout ce qui est dans ce portefeuille. Ne le partagez jamais, ne le saisissez jamais sur un autre site, et ne le regardez que lorsque personne ne peut voir votre écran."
 },
