 "modErrChanged": {
  "zh": "自本页加载以来媒体已发生变化，因此未应用任何更改。现在显示的是当前版本——请检查后再试。",
  "ko": "이 페이지가 로드된 이후 미디어가 변경되어 아무것도 적용되지 않았습니다. 현재 버전이 표시되고 있습니다 — 확인한 뒤 다시 시도하세요.",
  "es": "Los medios cambiaron desde que se cargó esta página, así que no se aplicó nada. Ahora se muestra la versión actual — revísala e inténtalo de nuevo.",
  "tr": "Bu sayfa yüklendiğinden beri medya değişti, bu yüzden hiçbir şey uygulanmadı. Şu anki sürüm gösteriliyor — lütfen kontrol edip tekrar deneyin.",
  "fa": "رسانه از زمانی که این صفحه بارگذاری شد تغییر کرده است، بنابراین چیزی اعمال نشد. نسخه کنونی اکنون نشان داده می‌شود — لطفاً آن را بررسی کنید و دوباره تلاش کنید.",
  "id": "Media telah berubah sejak halaman ini dimuat, jadi tidak ada yang diterapkan. Versi saat ini ditampilkan sekarang — silakan periksa dan coba lagi.",
  "vi": "Phương tiện đã thay đổi kể từ khi trang này được tải, nên không có gì được áp dụng. Phiên bản hiện tại đang được hiển thị — vui lòng kiểm tra và thử lại.",
  "th": "สื่อมีการเปลี่ยนแปลงตั้งแต่หน้านี้โหลด จึงไม่มีอะไรถูกนำไปใช้ เวอร์ชันปัจจุบันแสดงอยู่ตอนนี้ — โปรดตรวจสอบและลองอีกครั้ง",
  "it": "I media sono cambiati da quando questa pagina è stata caricata, quindi non è stato applicato nulla. Ora viene mostrata la versione attuale — controllala e riprova.",
  "pt": "A mídia mudou desde que esta página carregou, então nada foi aplicado. A versão atual está sendo mostrada agora — confira e tente de novo.",
  "nl": "De media zijn veranderd sinds deze pagina werd geladen, dus er is niets toegepast. De huidige versie wordt nu getoond — controleer die en probeer het opnieuw.",
  "pl": "Media zmieniły się od czasu wczytania tej strony, więc nic nie zostało zastosowane. Obecna wersja jest teraz pokazana — sprawdź ją i spróbuj ponownie.",
  "uk": "Медіа змінилися відтоді, як цю сторінку було завантажено, тому нічого не застосовано. Зараз показано поточну версію — перевірте її та спробуйте ще раз.",
  "de": "Die Medien haben sich geändert, seit diese Seite geladen wurde, daher wurde nichts angewendet. Der aktuelle Stand wird jetzt gezeigt — bitte prüfe ihn und versuche es erneut.",
  "ru": "Медиа изменились с тех пор, как эта страница была загружена, поэтому ничего не применено. Сейчас показана текущая версия — проверьте её и попробуйте ещё раз.",
  "ar": "تغيرت الوسائط منذ تحميل هذه الصفحة، لذا لم يُطبق شيء. تظهر النسخة الحالية الآن — يرجى التحقق منها والمحاولة مجدداً.",
  "hi": "इस पेज के लोड होने के बाद से मीडिया बदल गया है, इसलिए कुछ भी लागू नहीं किया गया। वर्तमान संस्करण अब दिखाया गया है — कृपया इसे जांचें और फिर से कोशिश करें।",
  "fr": "Les médias ont changé depuis le chargement de cette page, donc rien n’a été appliqué. La version actuelle est affichée maintenant — veuillez la vérifier et réessayer."
 },
