 "fcNeedWallet": {
  "zh": "先解锁发帖钱包——领取将发送到它的地址。",
  "ko": "먼저 게시 지갑을 잠금 해제하세요 — 청구는 그 주소로 전송됩니다.",
  "es": "Desbloquea primero la cartera de publicación — las reclamaciones se envían a su dirección.",
  "tr": "Önce gönderi cüzdanının kilidini açın — talepler onun adresine gönderilir.",
  "fa": "نخست کیف پول پست را باز کنید — ادعاها به نشانی آن فرستاده می‌شوند.",
  "id": "Buka kunci dompet posting terlebih dahulu — klaim dikirim ke alamatnya.",
  "vi": "Mở khóa ví đăng bài trước — các yêu cầu được gửi đến địa chỉ của nó.",
  "th": "ปลดล็อกกระเป๋าโพสต์ก่อน — การเคลมจะถูกส่งไปยังที่อยู่ของมัน",
  "it": "Sblocca prima il wallet di pubblicazione — le richieste sono inviate al suo indirizzo.",
  "pt": "Desbloqueie primeiro a carteira de publicação — as reivindicações são enviadas para o endereço dela.",
  "nl": "Ontgrendel eerst de posting-wallet — claims worden naar zijn adres gestuurd.",
  "pl": "Najpierw odblokuj portfel do postowania — roszczenia są wysyłane na jego adres.",
  "uk": "Спершу розблокуйте гаманець для публікацій — запити надсилаються на його адресу.",
  "de": "Entsperre zuerst die Posting-Wallet — Claims werden an ihre Adresse gesendet.",
  "ru": "Сначала разблокируйте кошелёк для публикаций — заявки отправляются на его адрес.",
  "ar": "افتح محفظة النشر أولاً — تُرسل المطالبات إلى عنوانها.",
  "hi": "पहले पोस्टिंग वॉलेट अनलॉक करें — दावे इसके पते पर भेजे जाते हैं।",
  "fr": "Déverrouillez d’abord le portefeuille de publication — les réclamations sont envoyées à son adresse."
 },
