  "ru": "В этом имени нет qCAW, поэтому действия не удадутся. Сначала положите в него немного qCAW (в разделе кошелька для публикаций).",
  "ar": "هذا الاسم لا يحتوي على qCAW، لذا ستفشل الإجراءات. ضع بعض qCAW فيه أولاً (في قسم محفظة النشر).",
  "hi": "इस नाम में qCAW नहीं है, इसलिए क्रियाएँ विफल होंगी। पहले इसमें कुछ qCAW डालें (पोस्टिंग वॉलेट अनुभाग में)।",
