 "bmNeedWallet": {
  "zh": "书签与此设备上的发帖钱包关联。解锁上方的发帖钱包以查看你保存的帖子。",
  "ko": "북마크는 이 기기의 게시 지갑에 연결되어 있습니다. 위의 게시 지갑을 잠금 해제하면 저장한 게시물을 볼 수 있습니다.",
  "es": "Los marcadores viven con tu cartera de publicación en este dispositivo. Desbloquea la cartera de publicación de arriba para ver las publicaciones que guardaste.",
  "tr": "Yer imleri bu cihazdaki gönderi cüzdanınızla yaşar. Kaydettiğiniz gönderileri görmek için yukarıdaki gönderi cüzdanının kilidini açın.",
  "fa": "نشانک‌ها با کیف پول پست شما روی این دستگاه زندگی می‌کنند. کیف پول پست بالا را باز کنید تا پست‌هایی را که ذخیره کرده‌اید ببینید.",
  "id": "Markah buku tinggal bersama dompet posting Anda di perangkat ini. Buka kunci dompet posting di atas untuk melihat postingan yang Anda simpan.",
  "vi": "Dấu trang sống cùng với ví đăng bài của bạn trên thiết bị này. Mở khóa ví đăng bài ở trên để xem các bài đăng bạn đã lưu.",
  "th": "บุ๊กมาร์กอยู่กับกระเป๋าโพสต์ของคุณบนอุปกรณ์นี้ ปลดล็อกกระเป๋าโพสต์ด้านบนเพื่อดูโพสต์ที่คุณบันทึกไว้",
  "it": "I segnalibri vivono con il tuo wallet di pubblicazione su questo dispositivo. Sblocca il wallet di pubblicazione qui sopra per vedere i post che hai salvato.",
  "pt": "Os favoritos ficam com sua carteira de publicação neste dispositivo. Desbloqueie a carteira de publicação acima para ver as publicações que você salvou.",
  "nl": "Bladwijzers leven met je posting-wallet op dit apparaat. Ontgrendel de posting-wallet hierboven om de berichten te zien die je hebt bewaard.",
  "pl": "Zakładki mieszkają z twoim portfelem do postowania na tym urządzeniu. Odblokuj portfel do postowania powyżej, aby zobaczyć zapisane posty.",
  "uk": "Закладки живуть із вашим гаманцем для публікацій на цьому пристрої. Розблокуйте гаманець для публікацій вище, щоб побачити збережені дописи.",
  "de": "Lesezeichen leben mit deiner Posting-Wallet auf diesem Gerät. Entsperre oben die Posting-Wallet, um die Beiträge zu sehen, die du gespeichert hast.",
  "ru": "Закладки живут с вашим кошельком для публикаций на этом устройстве. Разблокируйте кошелёк для публикаций выше, чтобы увидеть сохранённые посты.",
  "ar": "تعيش الإشارات المرجعية مع محفظة النشر الخاصة بك على هذا الجهاز. افتح محفظة النشر أعلاه لرؤية المنشورات التي حفظتها.",
  "hi": "बुकमार्क इस डिवाइस पर आपके पोस्टिंग वॉलेट के साथ रहते हैं। आपके द्वारा सहेजे गए पोस्ट देखने के लिए ऊपर दिए गए पोस्टिंग वॉलेट को अनलॉक करें।",
  "fr": "Les signets vivent avec votre portefeuille de publication sur cet appareil. Déverrouillez le portefeuille de publication ci-dessus pour voir les publications que vous avez enregistrées."
 },
 "ntNeedWallet": {
  "zh": "这些是对你的名字的反应。设置或解锁发帖钱包并选择一个名字，对它的反应就会出现在这里。",
  "ko": "여기에 표시되는 것은 당신의 이름에 대한 반응입니다. 게시 지갑을 준비(또는 잠금 해제)하고 이름을 선택하면 그 이름에 대한 반응이 여기에 나타납니다.",
  "es": "Estas son reacciones a TU nombre. Configura o desbloquea la cartera de publicación y elige un nombre, y las reacciones a él aparecerán aquí.",
  "tr": "Bunlar SİZİN isminize gelen tepkilerdir. Gönderi cüzdanını kurun veya kilidini açın ve bir isim seçin; ona gelen tepkiler burada görünecek.",
  "fa": "این‌ها واکنش‌ها به نام شما هستند. کیف پول پست را راه‌اندازی یا باز کنید و یک نام برگزینید تا واکنش‌ها به آن اینجا ظاهر شوند.",
  "id": "Ini adalah reaksi terhadap nama ANDA. Siapkan atau buka kunci dompet posting dan pilih nama, dan reaksi terhadapnya akan muncul di sini.",
  "vi": "Đây là các phản ứng đối với tên CỦA BẠN. Hãy thiết lập hoặc mở khóa ví đăng bài và chọn một tên, và các phản ứng đối với nó sẽ xuất hiện ở đây.",
  "th": "นี่คือปฏิกิริยาต่อชื่อของคุณ ตั้งค่าหรือปลดล็อกกระเป๋าโพสต์และเลือกชื่อ และปฏิกิริยาต่อชื่อนั้นจะปรากฏที่นี่",
  "it": "Queste sono reazioni al TUO nome. Configura o sblocca il wallet di pubblicazione e scegli un nome, e le reazioni a esso appariranno qui.",
  "pt": "Estas são reações ao SEU nome. Configure ou desbloqueie a carteira de publicação e escolha um nome, e as reações a ele aparecerão aqui.",
  "nl": "Dit zijn reacties op JOUW naam. Stel de posting-wallet in of ontgrendel hem en kies een naam, en reacties daarop verschijnen hier.",
  "pl": "To są reakcje na TWOJĄ nazwę. Skonfiguruj lub odblokuj portfel do postowania i wybierz nazwę, a reakcje na nią pojawią się tutaj.",
  "uk": "Це реакції на ВАШЕ ім’я. Налаштуйте або розблокуйте гаманець для публікацій і виберіть ім’я, і реакції на нього з’являться тут.",
  "de": "Dies sind Reaktionen auf DEINEN Namen. Richte die Posting-Wallet ein oder entsperre sie und wähle einen Namen, und Reaktionen darauf erscheinen hier.",
  "ru": "Это реакции на ВАШЕ имя. Настройте или разблокируйте кошелёк для публикаций и выберите имя, и реакции на него появятся здесь.",
  "ar": "هذه ردود فعل على اسمك. قم بإعداد محفظة النشر أو فتحها واختر اسماً، وستظهر ردود الفعل عليه هنا.",
  "hi": "ये आपके नाम पर प्रतिक्रियाएँ हैं। पोस्टिंग वॉलेट सेट करें या अनलॉक करें और एक नाम चुनें, और उस पर प्रतिक्रियाएँ यहाँ दिखाई देंगी।",
  "fr": "Ce sont les réactions à VOTRE nom. Configurez ou déverrouillez le portefeuille de publication et choisissez un nom, et les réactions à celui-ci apparaîtront ici."
 },
