 "mirrorWatchOff": {
  "zh": "X 自动监视：尚未配置——下方的收件箱和手动录入现在可用。",
  "ko": "X 자동 감시: 아직 설정되지 않았습니다 — 아래 받은편지함과 수동 가져오기는 지금 사용할 수 있습니다.",
  "es": "Vigilancia automática de X: aún no configurada — la bandeja de entrada y la entrada manual de abajo funcionan ahora.",
  "tr": "Otomatik X izleme: henüz yapılandırılmadı — aşağıdaki gelen kutusu ve manuel alım şimdi çalışıyor.",
  "fa": "تماشای خودکار X: هنوز پیکربندی نشده است — صندوق ورودی و دریافت دستی زیر هم‌اکنون کار می‌کنند.",
  "id": "Pengawasan X otomatis: belum dikonfigurasi — kotak masuk dan pengambilan manual di bawah berfungsi sekarang.",
  "vi": "Theo dõi X tự động: chưa được cấu hình — hộp thư đến và nhập thủ công bên dưới hoạt động ngay bây giờ.",
  "th": "การเฝ้าดู X อัตโนมัติ: ยังไม่ได้ตั้งค่า — กล่องจดหมายและการนำเข้าด้วยตนเองด้านล่างใช้งานได้ตอนนี้",
  "it": "Osservazione X automatica: non ancora configurata — la posta in arrivo e l’inserimento manuale qui sotto funzionano ora.",
  "pt": "Vigilância automática do X: ainda não configurada — a caixa de entrada e a entrada manual abaixo funcionam agora.",
  "nl": "Automatisch X-bewaken: nog niet ingesteld — de inbox en handmatige invoer hieronder werken nu al.",
  "pl": "Automatyczne obserwowanie X: jeszcze nieskonfigurowane — skrzynka odbiorcza i ręczne wprowadzanie poniżej działają już teraz.",
  "uk": "Автоматичне стеження за X: ще не налаштовано — вхідні та ручне внесення нижче працюють уже зараз.",
  "de": "Automatische X-Beobachtung: noch nicht eingerichtet — der Posteingang und die manuelle Übernahme unten funktionieren jetzt schon.",
  "ru": "Автоматическое наблюдение за X: ещё не настроено — входящие и ручной ввод ниже работают уже сейчас.",
  "ar": "مراقبة X التلقائية: غير مهيأة بعد — صندوق الوارد والإدخال اليدوي أدناه يعملان الآن.",
  "hi": "स्वचालित X वॉच: अभी कॉन्फ़िगर नहीं है — नीचे दिया गया इनबॉक्स और मैन्युअल इनटेक अभी काम करते हैं।",
  "fr": "Surveillance X automatique : pas encore configurée — la boîte de réception et la saisie manuelle ci-dessous fonctionnent dès maintenant."
 },
