 "tradeNeedUnlock": {
  "zh": "这会使用内置发帖钱包在本页内签名——请先设置或解锁它（在菜单中）。它从该钱包支出，而不是从钱包应用支出。",
  "ko": "이것은 이 페이지 내장 게시 지갑으로 서명합니다 — 먼저 (메뉴에서) 준비하거나 잠금을 해제하세요. 지갑 앱이 아니라 이 지갑에서 지불합니다.",
  "es": "Esto firma dentro de esta página con la cartera de publicación integrada — configúrala o desbloquéala primero (en el menú). Gasta desde esa cartera, no desde una app de cartera.",
  "tr": "Bu, bu sayfanın içinde yerleşik gönderi cüzdanıyla imzalar — önce onu kurun veya kilidini açın (menüde). Bir cüzdan uygulamasından değil, o cüzdandan harcar.",
  "fa": "این درون این صفحه با کیف پول پست داخلی امضا می‌شود — نخست آن را راه‌اندازی یا باز کنید (در منو). از آن کیف پول خرج می‌کند، نه از یک برنامه کیف پول.",
  "id": "Ini ditandatangani di dalam halaman ini dengan dompet posting bawaan — siapkan atau buka kuncinya terlebih dahulu (di menu). Ini membelanjakan dari dompet itu, bukan dari aplikasi dompet.",
  "vi": "Việc này ký bên trong trang này bằng ví đăng bài tích hợp — hãy thiết lập hoặc mở khóa nó trước (trong menu). Nó chi tiêu từ ví đó, không phải từ một ứng dụng ví.",
  "th": "สิ่งนี้ลงนามภายในหน้านี้ด้วยกระเป๋าโพสต์ในตัว — ตั้งค่าหรือปลดล็อกก่อน (ในเมนู) ใช้จ่ายจากกระเป๋านั้น ไม่ใช่จากแอปกระเป๋า",
  "it": "Questo firma dentro questa pagina con il wallet di pubblicazione integrato — configuralo o sbloccalo prima (nel menu). Spende da quel wallet, non da un’app wallet.",
  "pt": "Isto assina dentro desta página com a carteira de publicação integrada — configure-a ou desbloqueie-a primeiro (no menu). Gasta a partir dessa carteira, não de um app de carteira.",
  "nl": "Dit ondertekent binnen deze pagina met de ingebouwde posting-wallet — stel hem eerst in of ontgrendel hem (in het menu). Het geeft uit vanuit die wallet, niet vanuit een wallet-app.",
  "pl": "To podpisuje wewnątrz tej strony wbudowanym portfelem do postowania — najpierw go skonfiguruj lub odblokuj (w menu). Wydaje z tego portfela, nie z aplikacji portfelowej.",
  "uk": "Це підписується всередині цієї сторінки вбудованим гаманцем для публікацій — спершу налаштуйте або розблокуйте його (у меню). Витрачає з цього гаманця, а не із застосунку гаманця.",
  "de": "Dies signiert innerhalb dieser Seite mit der eingebauten Posting-Wallet — richte sie zuerst ein oder entsperre sie (im Menü). Es gibt aus dieser Wallet aus, nicht aus einer Wallet-App.",
  "ru": "Это подписывается внутри этой страницы встроенным кошельком для публикаций — сначала настройте или разблокируйте его (в меню). Тратит из этого кошелька, а не из приложения кошелька.",
  "ar": "يوقع هذا داخل هذه الصفحة بمحفظة النشر المدمجة — قم بإعدادها أو فتحها أولاً (في القائمة). ينفق من تلك المحفظة، وليس من تطبيق محفظة.",
  "hi": "यह इस पेज के अंदर बिल्ट-इन पोस्टिंग वॉलेट से साइन करता है — पहले इसे सेट करें या अनलॉक करें (मेनू में)। यह उस वॉलेट से खर्च करता है, वॉलेट ऐप से नहीं।",
  "fr": "Ceci signe à l’intérieur de cette page avec le portefeuille de publication intégré — configurez-le ou déverrouillez-le d’abord (dans le menu). Cela dépense depuis ce portefeuille, pas depuis une app de portefeuille."
 },
 "tradeGasWarn": {
  "zh": "此发帖钱包没有 QOM，因此无法支付小额费用。请先向它发送少量 QOM——它的地址在钱包页面上。",
  "ko": "이 게시 지갑에는 QOM이 없어 수수료를 지불할 수 없습니다. 먼저 QOM을 조금 보내세요 — 주소는 지갑 페이지에 있습니다.",
  "es": "Esta cartera de publicación no tiene QOM, así que no puede pagar las pequeñas comisiones. Envíale primero un poco de QOM — su dirección está en la página de Cartera.",
  "tr": "Bu gönderi cüzdanında QOM yok, bu yüzden küçük ücretleri ödeyemez. Önce ona biraz QOM gönderin — adresi Cüzdan sayfasındadır.",
  "fa": "این کیف پول پست QOM ندارد، بنابراین نمی‌تواند کارمزدهای کوچک را بپردازد. نخست کمی QOM برایش بفرستید — نشانی‌اش در صفحه کیف پول است.",
  "id": "Dompet posting ini tidak memiliki QOM, jadi tidak bisa membayar biaya kecil. Kirimkan sedikit QOM terlebih dahulu — alamatnya ada di halaman Dompet.",
  "vi": "Ví đăng bài này không có QOM, nên không thể trả các khoản phí nhỏ. Hãy gửi cho nó một ít QOM trước — địa chỉ của nó ở trên trang Ví.",
  "th": "กระเป๋าโพสต์นี้ไม่มี QOM จึงไม่สามารถจ่ายค่าธรรมเนียมเล็ก ๆ ได้ ส่ง QOM เล็กน้อยให้มันก่อน — ที่อยู่ของมันอยู่ที่หน้ากระเป๋าเงิน",
  "it": "Questo wallet di pubblicazione non contiene QOM, quindi non può pagare le piccole commissioni. Inviagli prima un po’ di QOM — il suo indirizzo è nella pagina Wallet.",
  "pt": "Esta carteira de publicação não tem QOM, então não pode pagar as pequenas taxas. Envie um pouco de QOM para ela primeiro — o endereço dela está na página Carteira.",
  "nl": "Deze posting-wallet bevat geen QOM, dus hij kan de kleine vergoedingen niet betalen. Stuur hem eerst een beetje QOM — zijn adres staat op de Wallet-pagina.",
  "pl": "Ten portfel do postowania nie ma QOM, więc nie może zapłacić małych opłat. Najpierw wyślij mu trochę QOM — jego adres jest na stronie Portfela.",
  "uk": "У цьому гаманці для публікацій немає QOM, тому він не може сплатити невеликі комісії. Спершу надішліть йому трохи QOM — його адреса на сторінці Гаманця.",
  "de": "Diese Posting-Wallet enthält kein QOM, daher kann sie die kleinen Gebühren nicht zahlen. Sende ihr zuerst etwas QOM — ihre Adresse steht auf der Wallet-Seite.",
  "ru": "В этом кошельке для публикаций нет QOM, поэтому он не может оплатить небольшие комиссии. Сначала отправьте ему немного QOM — его адрес на странице Кошелька.",
  "ar": "محفظة النشر هذه لا تحتوي على QOM، لذا لا يمكنها دفع الرسوم الصغيرة. أرسل إليها القليل من QOM أولاً — عنوانها في صفحة المحفظة.",
  "hi": "इस पोस्टिंग वॉलेट में QOM नहीं है, इसलिए यह छोटे शुल्क नहीं चुका सकता। पहले इसमें थोड़ा QOM भेजें — इसका पता वॉलेट पेज पर है।",
  "fr": "Ce portefeuille de publication ne contient aucun QOM, donc il ne peut pas payer les petits frais. Envoyez-lui d’abord un peu de QOM — son adresse est sur la page Portefeuille."
 },
