 "dexIntro": {
  "zh": "通过 QomSwap 路由器在 QL1 上兑换——与 Android 应用使用的同一个路由器。每个报价都从链上实时读取：没有路由的交易对不会显示报价，也无法兑换。",
  "ko": "QomSwap 라우터로 QL1에서 교환합니다 — Android 앱과 같은 라우터입니다. 견적은 모두 체인에서 그 자리에서 읽습니다. 경로가 없는 페어는 견적이 나오지 않고 교환도 할 수 없습니다.",
  "es": "Intercambia en QL1 a través del router QomSwap — el mismo router que usa la app de Android. Cada cotización se lee en vivo desde la cadena: un par sin ruta no muestra cotización y no se puede intercambiar.",
  "tr": "QomSwap yönlendiricisi üzerinden QL1’de takas yapın — Android uygulamasının kullandığı yönlendiricinin aynısı. Her teklif zincirden canlı okunur: rotası olmayan bir çift teklif göstermez ve takas edilemez.",
  "fa": "روی QL1 از راه روتر QomSwap مبادله کنید — همان روتری که برنامه اندروید استفاده می‌کند. هر قیمت به‌صورت زنده از زنجیره خوانده می‌شود: جفتی بدون مسیر قیمتی نشان نمی‌دهد و نمی‌توان آن را مبادله کرد.",
  "id": "Tukar di QL1 melalui router QomSwap — router yang sama yang digunakan aplikasi Android. Setiap kutipan dibaca langsung dari rantai: pasangan tanpa rute tidak menampilkan kutipan dan tidak bisa ditukar.",
  "vi": "Hoán đổi trên QL1 qua bộ định tuyến QomSwap — cùng bộ định tuyến mà ứng dụng Android dùng. Mọi báo giá đều được đọc trực tiếp từ chuỗi: một cặp không có tuyến đường sẽ không hiển thị báo giá và không thể hoán đổi.",
  "th": "แลกเปลี่ยนบน QL1 ผ่านเราเตอร์ QomSwap — เราเตอร์เดียวกับที่แอป Android ใช้ ทุกใบเสนอราคาอ่านสดจากเชน: คู่ที่ไม่มีเส้นทางจะไม่แสดงใบเสนอราคาและไม่สามารถแลกเปลี่ยนได้",
  "it": "Scambia su QL1 attraverso il router QomSwap — lo stesso router che usa l’app Android. Ogni quotazione è letta in diretta dalla chain: una coppia senza rotta non mostra quotazione e non può essere scambiata.",
  "pt": "Troque na QL1 através do roteador QomSwap — o mesmo roteador que o app Android usa. Cada cotação é lida ao vivo da cadeia: um par sem rota não mostra cotação e não pode ser trocado.",
  "nl": "Swap op QL1 via de QomSwap-router — dezelfde router die de Android-app gebruikt. Elke offerte wordt live van de chain gelezen: een paar zonder route toont geen offerte en kan niet worden geswapt.",
  "pl": "Wymieniaj na QL1 przez router QomSwap — ten sam router, którego używa aplikacja na Androida. Każda wycena jest odczytywana na żywo z łańcucha: para bez trasy nie pokazuje wyceny i nie może być wymieniona.",
  "uk": "Обмін на QL1 через маршрутизатор QomSwap — той самий маршрутизатор, що використовує застосунок для Android. Кожна котировка читається наживо з ланцюга: пара без маршруту не показує котировки й не може бути обміняна.",
  "de": "Swap auf QL1 über den QomSwap-Router — derselbe Router, den die Android-App nutzt. Jedes Angebot wird live von der Chain gelesen: ein Paar ohne Route zeigt kein Angebot und kann nicht geswappt werden.",
  "ru": "Обмен на QL1 через маршрутизатор QomSwap — тот же маршрутизатор, что использует приложение для Android. Каждая котировка читается вживую с цепочки: пара без маршрута не показывает котировки и не может быть обменяна.",
  "ar": "بادل على QL1 عبر موجه QomSwap — نفس الموجه الذي يستخدمه تطبيق Android. تُقرأ كل تسعيرة مباشرة من السلسلة: الزوج الذي لا طريق له لا يعرض تسعيرة ولا يمكن مبادلته.",
  "hi": "QomSwap राउटर के माध्यम से QL1 पर स्वैप करें — वही राउटर जो Android ऐप उपयोग करता है। हर कोट चेन से लाइव पढ़ा जाता है: बिना रूट वाला जोड़ा कोई कोट नहीं दिखाता और स्वैप नहीं किया जा सकता।",
  "fr": "Échangez sur QL1 via le routeur QomSwap — le même routeur que l’app Android utilise. Chaque devis est lu en direct depuis la chaîne : une paire sans route n’affiche aucun devis et ne peut pas être échangée."
 },
