 "modSanctionNote": {
  "ar": "ستختفي منشوراتهم من كل شاشات هذا التطبيق ونسخة الويب عن الجميع عدا المشرفين، ولن يتمكنوا من رفع الوسائط. تبقى المنشورات في السجل العام (على السلسلة)، وقد تستمر برامج أخرى في إظهارها.",
  "de": "Ihre Beiträge verschwinden von jedem Bildschirm dieser App und des Web-Viewers für alle außer Moderatoren, und sie können keine Medien hochladen. Die Beiträge bleiben im öffentlichen Register (on-chain), und andere Clients können sie weiterhin anzeigen.",
  "es": "Sus publicaciones desaparecerán de todas las pantallas de esta app y del visor web para todos excepto los moderadores, y no podrán subir archivos. Las publicaciones permanecen en el registro público (en la cadena) y otros clientes pueden seguir mostrándolas.",
  "fa": "پست‌های آن‌ها از همهٔ صفحه‌های این برنامه و نسخهٔ وب برای همه به‌جز مدیران پنهان می‌شود و نمی‌توانند رسانه بارگذاری کنند. پست‌ها در سابقهٔ عمومی (روی زنجیره) می‌مانند و کلاینت‌های دیگر ممکن است همچنان آن‌ها را نشان دهند.",
  "fr": "Leurs publications disparaîtront de tous les écrans de cette application et de la version web pour tout le monde sauf les modérateurs, et ils ne pourront plus téléverser de médias. Les publications restent dans le registre public (sur la chaîne), et d’autres clients peuvent continuer à les afficher.",
  "hi": "उनकी पोस्ट इस ऐप और वेब व्यूअर की हर स्क्रीन से मॉडरेटर के अलावा सभी के लिए गायब हो जाएँगी, और वे मीडिया अपलोड नहीं कर पाएँगे। पोस्ट सार्वजनिक रिकॉर्ड (ऑन-चेन) में बनी रहती हैं, और अन्य क्लाइंट उन्हें दिखाते रह सकते हैं।",
  "id": "Postingan mereka akan hilang dari setiap layar aplikasi ini dan penampil web untuk semua orang kecuali moderator, dan mereka tidak bisa mengunggah media. Postingan tetap ada di catatan publik (on-chain), dan klien lain mungkin masih menampilkannya.",
  "it": "I loro post spariranno da ogni schermata di questa app e del visualizzatore web per tutti tranne i moderatori, e non potranno caricare media. I post restano nel registro pubblico (on-chain) e altri client potrebbero continuare a mostrarli.",
  "ko": "그들의 게시물은 이 앱과 웹 뷰어의 모든 화면에서 운영자 외의 모든 사람에게 보이지 않게 되며, 미디어도 업로드할 수 없습니다. 게시물은 공개 기록(온체인)에 남고, 다른 클라이언트에서는 표시될 수 있습니다.",
  "nl": "Hun berichten verdwijnen van elk scherm van deze app en webviewer voor iedereen behalve moderators, en ze kunnen geen media uploaden. De berichten blijven in het openbare register (on-chain) staan en andere clients kunnen ze blijven tonen.",
  "pl": "Ich posty znikną z każdego ekranu tej aplikacji i przeglądarki internetowej dla wszystkich poza moderatorami i nie będą mogli przesyłać multimediów. Posty pozostają w publicznym rejestrze (on-chain), a inne klienty mogą je nadal pokazywać.",
  "pt": "As publicações deles desaparecerão de todas as telas deste app e do visualizador web para todos, exceto moderadores, e eles não poderão enviar mídia. As publicações permanecem no registro público (on-chain), e outros clientes podem continuar a mostrá-las.",
  "ru": "Их посты исчезнут с каждого экрана этого приложения и веб-версии для всех, кроме модераторов, и они не смогут загружать медиа. Посты остаются в публичном реестре (на цепочке), и другие клиенты могут продолжать их показывать.",
  "th": "โพสต์ของพวกเขาจะหายไปจากทุกหน้าจอของแอปนี้และเว็บสำหรับทุกคนยกเว้นผู้ดูแล และจะอัปโหลดสื่อไม่ได้ โพสต์ยังคงอยู่ในบันทึกสาธารณะ (บนเชน) และไคลเอนต์อื่นอาจยังแสดงอยู่",
  "tr": "Gönderileri, bu uygulamanın ve web görüntüleyicinin her ekranında moderatörler dışında herkesten gizlenir ve medya yükleyemezler. Gönderiler herkese açık kayıtta (zincir üzerinde) kalır ve başka istemciler bunları göstermeye devam edebilir.",
  "uk": "Їхні дописи зникнуть з кожного екрана цього застосунку та вебпереглядача для всіх, крім модераторів, і вони не зможуть завантажувати медіа. Дописи залишаються в публічному реєстрі (на ланцюгу), й інші клієнти можуть і далі їх показувати.",
  "vi": "Bài viết của họ sẽ biến mất khỏi mọi màn hình của ứng dụng này và bản web đối với mọi người trừ người điều hành, và họ không thể tải lên phương tiện. Bài viết vẫn nằm trong hồ sơ công khai (trên chuỗi), và các ứng dụng khác vẫn có thể hiển thị chúng.",
  "zh": "他们的帖子将在本应用和网页版的每个界面上对除管理员外的所有人隐藏，且无法上传媒体。帖子仍保留在公开记录（链上），其他客户端可能仍会显示。"
 },
