 "Built from the public record since you last opened this page. This is not a complete all-time history.": {
  "zh": "根据你上次打开本页以来的公开记录构建。这不是完整的历史记录。",
  "ko": "지난번에 이 페이지를 연 이후의 공개 기록으로 만들었습니다(전 기간의 완전한 기록은 아닙니다).",
  "es": "Construido desde el registro público desde la última vez que abriste esta página. No es un historial completo de todos los tiempos.",
  "tr": "Bu sayfayı son açışınızdan bu yana kamuya açık kayıttan oluşturuldu. Bu, tüm zamanların eksiksiz bir geçmişi değildir.",
  "fa": "از سابقه عمومی از آخرین باری که این صفحه را باز کردید ساخته شده است. این تاریخچه کامل همه زمان‌ها نیست.",
  "id": "Dibangun dari catatan publik sejak terakhir kali Anda membuka halaman ini. Ini bukan riwayat lengkap sepanjang masa.",
  "vi": "Được dựng từ hồ sơ công khai kể từ lần cuối bạn mở trang này. Đây không phải là lịch sử đầy đủ của mọi thời đại.",
  "th": "สร้างจากบันทึกสาธารณะตั้งแต่ครั้งสุดท้ายที่คุณเปิดหน้านี้ นี่ไม่ใช่ประวัติทั้งหมดตลอดกาล",
  "it": "Costruito dal registro pubblico dall’ultima volta che hai aperto questa pagina. Non è uno storico completo di tutti i tempi.",
  "pt": "Construído a partir do registro público desde a última vez que você abriu esta página. Não é um histórico completo de todos os tempos.",
  "nl": "Opgebouwd uit het openbare register sinds je deze pagina voor het laatst opende. Dit is geen volledige geschiedenis van alle tijden.",
  "pl": "Zbudowane z publicznego zapisu od czasu, gdy ostatnio otworzyłeś tę stronę. To nie jest pełna historia wszech czasów.",
  "uk": "Побудовано з публічного запису відтоді, як ви востаннє відкривали цю сторінку. Це не повна історія всіх часів.",
  "de": "Aufgebaut aus dem öffentlichen Datensatz, seit du diese Seite zuletzt geöffnet hast. Dies ist keine vollständige Historie aller Zeiten.",
  "ru": "Построено из публичной записи с тех пор, как вы в последний раз открывали эту страницу. Это не полная история всех времён.",
  "ar": "مبني من السجل العام منذ آخر مرة فتحت فيها هذه الصفحة. هذا ليس تاريخاً كاملاً لكل الأزمان.",
  "hi": "जब से आपने आखिरी बार यह पेज खोला था, तब से सार्वजनिक रिकॉर्ड से बनाया गया। यह सभी समय का पूरा इतिहास नहीं है।",
  "fr": "Construit à partir du registre public depuis votre dernière ouverture de cette page. Ce n’est pas un historique complet de tous les temps."
 },
